import { bot, expire } from "./bot.js";
import { startApi } from "./api.js";
import { db } from "./db.js";
import { processReminders } from "./reminders.js";
const server = startApi();
await expire();
await processReminders();
const timer = setInterval(() => { expire().catch(console.error); processReminders().catch(console.error); }, 30000);
bot.start({ onStart: async (i) => { console.log(`Bot @${i.username} started`); await bot.api.setMyCommands([{ command: "start", description: "Открыть Ravvo" }, { command: "menu", description: "Панель управления" }, { command: "help", description: "Справка по командам" }, { command: "settings", description: "Настройки группы" }, { command: "order", description: "Заказать Java-плагин" }, { command: "ban", description: "Заблокировать участника" }, { command: "unban", description: "Снять блокировку" }, { command: "kick", description: "Исключить участника" }, { command: "mute", description: "Ограничить участника" }, { command: "unmute", description: "Снять ограничения" }, { command: "warn", description: "Выдать предупреждение" }, { command: "unwarn", description: "Снять предупреждение" }, { command: "warns", description: "Показать предупреждения" }, { command: "delete", description: "Удалить сообщение" }, { command: "purge", description: "Удалить диапазон сообщений" }, { command: "info", description: "Информация об участнике" }, { command: "staff", description: "Команда группы" }, { command: "rules", description: "Правила группы" }, { command: "announce", description: "Опубликовать объявление" }, { command: "pin", description: "Закрепить сообщение" }, { command: "silence", description: "Включить режим тишины" }, { command: "unsilence", description: "Выключить режим тишины" }, { command: "report", description: "Пожаловаться на сообщение" }]); await bot.api.setMyDefaultAdministratorRights({ for_channels: false, rights: { is_anonymous: false, can_manage_chat: true, can_delete_messages: true, can_manage_video_chats: true, can_restrict_members: true, can_promote_members: false, can_change_info: true, can_invite_users: true, can_post_stories: false, can_edit_stories: false, can_delete_stories: false, can_pin_messages: true, can_manage_topics: true } }); await bot.api.setChatMenuButton({ menu_button: { type: "commands" } }); console.log("Telegram command menu configured; web app disabled"); } });
async function stop() { clearInterval(timer); bot.stop(); server.close(); await db.$disconnect(); process.exit(0); }
process.once("SIGINT", stop);
process.once("SIGTERM", stop);
